import sys
import heapq

def main():
    import sys
    import heapq

    def read_ints():
        return list(map(int, sys.stdin.readline().split()))

    N, M = read_ints()

    # Initialize the graph
    graph = [[] for _ in range(N)]

    # Read the trains and build the graph
    for _ in range(M):
        X, S, T, L = read_ints()
        X -= 1  # Convert to 0-based index
        # Add the train as an edge with weight L
        graph[X].append((X + 1, L))
        graph[X + 1].append((X, L))

    # Function to find the earliest start time
    def find_earliest_start_time():
        # Priority queue for Dijkstra's algorithm
        pq = []
        # Distance array to store the minimum delay needed to reach each station
        dist = [float('inf')] * N
        # Start from station 1 (index 0)
        heapq.heappush(pq, (0, 0))
        dist[0] = 0

        while pq:
            current_delay, current_station = heapq.heappop(pq)

            if current_station == N - 1:
                return current_delay

            for neighbor, delay in graph[current_station]:
                new_delay = current_delay + delay
                if new_delay < dist[neighbor]:
                    dist[neighbor] = new_delay
                    heapq.heappush(pq, (new_delay, neighbor))

        return float('inf')

    earliest_start_time = find_earliest_start_time()

    if earliest_start_time == float('inf'):
        print("impossible")
    else:
        print(earliest_start_time)

if __name__ == "__main__":
    main()
